const NAV=[['home','⌂','Panoramica'],['clima','♨','Clima'],['luci','☀','Luci'],['sicurezza','⬡','Sicurezza'],['tende','▤','Tende'],['media','▣','Multimedia'],['sistema','▥','Sistema'],['ambienti','◈','Ambienti'],['impostazioni','⚙','Impostazioni']];
const E={weather:'weather.casa',temp:'sensor.temperatura_salotto_netatmo',humid:'sensor.termometro_camera_humidity',outtemp:'sensor.meteopb_temperatura',outhumid:'sensor.meteopb_umidita',power:'sensor.shellyemg3_b08184e86778_energy_meter_0_power',alarm:'alarm_control_panel.alarmo',door:'lock.porta_ingresso',lights:'sensor.luci_accese',thermo:'climate.netatmo_smart_thermostat',ac:'climate.daikinap54003',camera:'camera.tapo_hd_stream',vacuum:'vacuum.l40_ultra_ae'};
const GROUPS={luci:[['💡','Piantana salotto','light.salotto'],['💡','Abat-jour','light.abatjour'],['💡','Bagno','light.bagno'],['💡','Terrazza cucina','light.luce_terrazza_cucina'],['💡','Terrazza camera','light.luce_terrazza_letto'],['💡','Terrazza parco','light.luce_terrazza_parco'],['💡','Luce sottotetto','light.luce_sottotetto'],['✨','Nanoleaf TV','light.4d_f59b'],['💡','Garage','light.shelly1_349454741da8']],tende:[['▤','Tenda Parco','cover.shellyswitch25_68e7a1'],['▤','Tenda Cucina','cover.shellyplus2pm_fcb46726ef20_cover_0'],['▤','Tenda Camera','cover.shellyplus2pm_e86beae91850_cover_0']],sicurezza:[['🚪','Ingresso','binary_sensor.porta_ingresso_contact'],['🪟','Finestra salotto','binary_sensor.finestra_salotto_contact'],['🪟','Finestra cucina','binary_sensor.finestra_cucina_contact'],['🪟','Finestra camera','binary_sensor.finestra_camera_da_letto_contact'],['🚘','Basculante garage','binary_sensor.sonoff_10024825a0']],sistema:[['🔋','Finestra salotto','sensor.finestra_salotto_battery'],['🔋','Finestra cucina','sensor.finestra_cucina_battery'],['🔋','Termostato','sensor.termostato_battery_percent_2'],['🔋','Nuki','sensor.porta_ingresso_battery_2'],['🔋','Telecomando IKEA','sensor.telecomando_ikea_battery'],['🔋','Ring Intercom','sensor.ingresso_batteria'],['🔋','Garage','sensor.sonoff_10024825a0_battery']]};
const PREF_KEY='aveniq_prefs_v04';
const defaults={theme:'light',compact:false,showHero:true,showStatus:true,showWidgets:true,showQuick:true,powerUnit:'auto',names:{},entityMap:{}};
let prefs={...defaults};
try{const saved=JSON.parse(localStorage.getItem(PREF_KEY)||'{}');prefs={...defaults,...saved,names:saved.names||{},entityMap:saved.entityMap||{}};}catch(_){}
let view='home', states={}, loading=true, connected=false, requestRunning=false;
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
Object.keys(prefs.entityMap).forEach(k=>{if(Object.prototype.hasOwnProperty.call(E,k)&&/^[a-z_]+\.[a-z0-9_]+$/.test(prefs.entityMap[k]))E[k]=prefs.entityMap[k]});
const S=id=>states[id]||null, val=id=>S(id)?.state??'—', valid=id=>S(id)&&!['unknown','unavailable'].includes(val(id)), unit=id=>S(id)?.attributes?.unit_of_measurement||'', fmt=id=>valid(id)?`${esc(val(id))}${esc(unit(id))}`:'—', pct=id=>Math.max(0,Math.min(100,Number(val(id))||0));
const isOn=id=>['on','open','opening','heat','cool','heating','playing'].includes(val(id));
const section=(name,note='')=>`<div class="sectionline"><h3>${esc(name)}</h3><small>${esc(note)}</small></div>`;
const PANEL_TITLES={'Energia':'energy','Consumo':'energy','Clima':'climate','Temperatura interna':'climate','Luci accese':'lights','Tende disponibili':'covers','Batteria più bassa':'batteries','Porta ingresso':'door','Porta principale':'door','Finestre aperte':'contacts'};
const tile=(icon,title,value,sub='',tint='')=>{const p=PANEL_TITLES[title];return `<${p?'button type="button" data-panel="'+p+'"':'div'} class="card ${tint} ${p?'detail-tile':''}" ${p?'aria-label="Apri dettagli '+esc(title)+'"':''}><div class="iconbox">${icon}</div><h4>${esc(title)}</h4><div class="metric">${esc(value)}</div><div class="sub">${esc(sub)}${p?' · Dettagli ↗':''}</div></${p?'button':'div'}>`};
const alarmTile=()=>`<button type="button" class="card tint-teal alarm-tile" data-open-alarm aria-label="Apri controlli antifurto"><div class="iconbox">🛡️</div><h4>Antifurto</h4><div class="metric">${esc(alarmLabel())}</div><div class="sub">Alarmo · Tocca per gestire ↗</div></button>`;
const alarmLabel=()=>({disarmed:'Disattivo',armed_away:'Inserito',armed_home:'In casa',armed_night:'Notturno',arming:'Inserimento…',pending:'Attesa…',triggered:'ALLARME ATTIVO'})[val(E.alarm)]||val(E.alarm);
const alarmModal=()=>`<div class="alarm-backdrop" data-close-alarm><section role="dialog" aria-modal="true" aria-labelledby="alarm-dialog-title" class="alarm-dialog" data-alarm-dialog><div class="alarm-head"><div><div class="eyebrow">Protezione della casa</div><h2 id="alarm-dialog-title">🛡️ Antifurto</h2></div><button class="alarm-close" type="button" data-close-alarm aria-label="Chiudi">✕</button></div><div class="alarm-state"><span class="alarm-dot ${val(E.alarm)==='disarmed'?'idle':'armed'}"></span><div><small>Stato attuale</small><strong>${esc(alarmLabel())}</strong></div></div><p class="alarm-help">Gestisci Alarmo. L'inserimento o il disinserimento possono richiedere il codice configurato in Home Assistant.</p><label class="alarm-code-label" for="alarm-code">Codice Alarmo (se richiesto)</label><input id="alarm-code" class="alarm-code" type="password" inputmode="numeric" autocomplete="off" placeholder="Non viene salvato"><div class="alarm-actions"><button type="button" data-alarm-command="alarm_arm_away">🏠 Inserimento totale</button><button type="button" data-alarm-command="alarm_arm_night">☾ Modalità notte</button><button type="button" data-alarm-command="alarm_disarm" class="danger">◯ Disinserisci</button></div><div class="alarm-feedback" role="status" aria-live="polite"></div><div class="alarm-contacts"><strong>Sensori di apertura</strong>${GROUPS.sicurezza.map(([icon,label,id])=>`<div><span>${icon} ${esc(label)}</span><b>${!valid(id)?'Non disponibile':isOn(id)?'Aperto':'Chiuso'}</b></div>`).join('')}</div></section></div>`;
function openAlarm(){document.querySelector('.alarm-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',alarmModal());document.querySelector('[data-alarm-command]')?.focus();document.querySelectorAll('[data-close-alarm]').forEach(el=>el.addEventListener('click',e=>{if(e.target===el || el.classList.contains('alarm-close'))document.querySelector('.alarm-backdrop')?.remove()}));document.querySelectorAll('[data-alarm-command]').forEach(el=>el.addEventListener('click',()=>alarmCommand(el.dataset.alarmCommand)));}
async function alarmCommand(service){if(requestRunning||!valid(E.alarm))return;const codeEl=document.querySelector('#alarm-code'),code=codeEl?.value||'';const box=document.querySelector('.alarm-feedback');if(!box)return;const label={alarm_arm_away:'inserimento totale',alarm_arm_night:'inserimento notte',alarm_disarm:'disinserimento'}[service];if(!window.confirm('Confermi '+label+' dell’antifurto?'))return;requestRunning=true;box.textContent='Invio comando…';document.querySelectorAll('[data-alarm-command]').forEach(el=>el.disabled=true);try{const res=await fetch('api/service',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({domain:'alarm_control_panel',service,entity_id:E.alarm,data:code?{code}:{}})});const data=await res.json();if(!res.ok)throw Error(data.error||'Comando non riuscito');box.textContent='Comando inviato. In attesa dello stato aggiornato…';toast('Comando Alarmo inviato');}catch(err){box.textContent='Errore: '+err.message;toast('Errore Alarmo: '+err.message)}finally{if(codeEl)codeEl.value='';requestRunning=false;document.querySelectorAll('[data-alarm-command]').forEach(el=>el.disabled=false);await refresh();}}
const nav=()=>NAV.map(([key,icon,title])=>`<button type="button" data-view="${key}" class="${view===key?'active':''}">${icon} <span>${title}</span></button>`).join('');
const button=(title,domain,service,id,extra={})=>`<button class="action ${service==='turn_on'||service==='open_cover'?'primary':''}" data-domain="${domain}" data-service="${service}" data-id="${esc(id)}" data-extra="${encodeURIComponent(JSON.stringify(extra))}" ${!valid(id)?'disabled':''}>${esc(title)}</button>`;
const device=([icon,name,id])=>{const state=val(id), domain=id.split('.')[0];let controls='';if(valid(id)&&domain==='light')controls=button(isOn(id)?'Spegni':'Accendi','light',isOn(id)?'turn_off':'turn_on',id);if(valid(id)&&domain==='cover')controls=button('↑','cover','open_cover',id)+button('■','cover','stop_cover',id)+button('↓','cover','close_cover',id);if(valid(id)&&domain==='switch')controls=button(isOn(id)?'Off':'On','switch',isOn(id)?'turn_off':'turn_on',id);return `<div class="item"><div class="glyph">${icon}</div><div class="item-main"><strong>${esc(name)}</strong><small>${esc(state)}</small></div><div class="controls">${controls||`<span class="pill ${state==='unavailable'?'bad':''}">${domain==='sensor'?fmt(id):esc(state)}</span>`}</div></div>`};
function statusCards(){return `<div class="grid four">${alarmTile()}${tile('🔒','Porta ingresso',val(E.door)==='locked'?'Bloccata':val(E.door),'Nuki','tint-rose')}${tile('💡','Luci accese',fmt(E.lights),'Totale rilevato','tint-orange')}${tile('▤','Tende disponibili',GROUPS.tende.filter(x=>valid(x[2])).length+'/3','Shelly','tint-violet')}</div>`}
function home(){return `${prefs.showHero?`<div class="hero"><div class="eyebrow" style="color:#d3f8f5">La tua casa, a colpo d'occhio</div><h2>Buongiorno, Elia</h2><p>${esc(val(E.weather))} · Informazioni in tempo reale</p><div class="hero-stats"><div class="hero-stat"><strong>${fmt(E.outtemp)}</strong><small>Temperatura esterna</small></div><div class="hero-stat"><strong>${fmt(E.temp)}</strong><small>Clima interno</small></div><div class="hero-stat"><strong>${fmt(E.humid)}</strong><small>Umidità</small></div><div class="hero-stat"><strong>${fmt(E.power)}</strong><small>Potenza istantanea</small></div></div></div>`:''}${prefs.showStatus?section('La casa adesso','Tocca per controllare')+statusCards():''}${section('Ambienti','La tua casa, stanza per stanza')}${homeRooms()}${widgetConfigs.length?section('Widget personali','Configurati da Impostazioni')+widgetsBlock():''}${prefs.showWidgets?section('Widget','Dati in tempo reale')+`<div class="grid four">${tile('⚡','Energia',fmt(E.power),'Potenza istantanea','tint-orange')}${tile('🌡️','Clima',fmt(E.temp),'Umidità '+fmt(E.humid),'tint-teal')}${tile('🪟','Finestre aperte',GROUPS.sicurezza.filter(x=>x[2].includes('finestra')&&isOn(x[2])).length,'Sensori contatto','tint-rose')}${tile('🔋','Batteria più bassa',(()=>{const n=GROUPS.sistema.filter(x=>valid(x[2])).map(x=>Number(val(x[2]))).filter(Number.isFinite);return n.length?Math.min(...n)+'%':'—'})(),'Dispositivi monitorati','tint-violet')}</div>`:''}${prefs.showQuick?section('Controlli rapidi','Dispositivi preferiti')+`<div class="device-list">${GROUPS.luci.slice(0,4).map(device).join('')}${GROUPS.tende.slice(1).map(device).join('')}</div>`:''}`}

function climate(){return `${section('Clima interno ed esterno')}<div class="grid four">${tile('🌡️','Temperatura interna',fmt(E.temp),'Salotto','tint-teal')}${tile('💧','Umidità interna',fmt(E.humid),'Camera','tint-orange')}${tile('☁️','Temperatura esterna',fmt(E.outtemp),'Meteo PB','tint-violet')}${tile('💦','Umidità esterna',fmt(E.outhumid),'Meteo PB','tint-teal')}</div>${section('Termostati e climatizzazione')}<div class="grid two">${climateDevice('Riscaldamento Netatmo',E.thermo)}${climateDevice('Climatizzatore Daikin',E.ac)}</div>${section('Pulizia')}<div class="card"><div class="item"><div class="glyph">🤖</div><div class="item-main"><strong>Dreame L40 Ultra AE</strong><small>${esc(val(E.vacuum))}</small></div><div class="controls">${button('Avvia','vacuum','start',E.vacuum)}${button('Base','vacuum','return_to_base',E.vacuum)}</div></div></div>`}
function climateDevice(title,id){return `<div class="card"><h4>${title}</h4><div class="metric">${esc(S(id)?.attributes?.current_temperature??'—')} °C</div><div class="sub">${esc(val(id))} · Target ${esc(S(id)?.attributes?.temperature??'—')} °C</div><div class="tabs">${button('Spento','climate','set_hvac_mode',id,{hvac_mode:'off'})}${button('Riscalda','climate','set_hvac_mode',id,{hvac_mode:'heat'})}${button('Raffresca','climate','set_hvac_mode',id,{hvac_mode:'cool'})}</div></div>`}
function security(){return `${section('Protezione e accessi')}<div class="grid three">${alarmTile()}${tile('🔒','Porta principale',val(E.door),'Sblocco escluso per sicurezza','tint-rose')}${tile('📹','Telecamera Tapo',val(E.camera),'Streaming in una release successiva','tint-violet')}</div>${section('Contatti e aperture')}<div class="device-list">${GROUPS.sicurezza.map(device).join('')}</div><p class="banner">Per sicurezza, questa prima versione è di sola lettura per serratura, antifurto e accessi. La serratura rimane in sola lettura. Alarmo dispone ora di un pannello dedicato.</p>`}
function lights(){return `${section('Illuminazione','Controlli stanza per stanza')}<div class="device-list">${GROUPS.luci.map(device).join('')}</div><p class="banner">I comandi ON/OFF sono già operativi. Dimmer e palette RGB sono previsti nella prossima versione.</p>`}
function covers(){return `${section('Tende motorizzate','Shelly')}<div class="device-list">${GROUPS.tende.map(device).join('')}</div>`}
function media(){return `${section('Multimedia')}${kodiRemote()}<div class="grid three">${tile('🎬','Kodi','Bridge pronto','Integrazione dei comandi personalizzati in sviluppo','tint-teal')}${tile('📺','Televisione','Samsung','Da collegare alle entità media_player','tint-violet')}${tile('🎮','Moonlight','Prossimamente','Modulo remoto dedicato','tint-orange')}</div><div class="banner" style="margin-top:18px">Questa release non sostituisce ancora il telecomando Kodi Smart Bridge esistente.</div>`}
function system(){return `${section('Stato host e infrastruttura')}${diagnostics()}<div class="grid four">${tile('🖥️','Proxmox CPU',fmt('sensor.node_proxmox_cpu_usata'),'Utilizzo CPU','tint-teal')}${tile('🌡️','Proxmox temperatura',fmt('sensor.proxmox_cpu_temp'),'CPU','tint-orange')}${tile('🔌','UPS',fmt('sensor.apcups_carica_batterie'),'Carica batteria','tint-violet')}${tile('⚡','Consumo',fmt(E.power),'Energia elettrica','tint-rose')}</div>${section('Batterie','Dispositivi Zigbee e accessori')}<div class="device-list">${GROUPS.sistema.map(device).join('')}</div>${section('Servizi')}<div class="card"><div class="item"><span>🛡️</span><div class="item-main"><strong>Pi-hole</strong><small>${esc(val('switch.pi_hole'))}</small></div></div><div class="item"><span>🖥️</span><div class="item-main"><strong>Proxmox</strong><small>${esc(val('binary_sensor.node_proxmox_stato'))}</small></div></div></div>`}


/* Aveniq v0.5: shared configuration + configurable room inventory + widget studio */
const SHARED_FIELDS=['rooms','widgets','theme','compact','entityMap','showHero','showStatus','showWidgets','showQuick'];
let roomAssignments={},widgetConfigs=[],configReady=false;
const DEFAULT_ROOMS=['Salotto','Cucina','Camera','Bagno','Garage','Terrazza'];
async function loadSharedConfig(){try{const resp=await fetch('api/config',{cache:'no-store'});if(!resp.ok)throw Error('config');const saved=(await resp.json()).config||{};roomAssignments=saved.rooms||{};widgetConfigs=saved.widgets||[];for(const key of SHARED_FIELDS){if(key in saved && key!=='rooms'&&key!=='widgets')prefs[key]=saved[key]}if(prefs.entityMap)for(const [key,id] of Object.entries(prefs.entityMap)){if(Object.hasOwn(E,key)&&/^[a-z_]+\.[a-z0-9_]+$/.test(id))E[key]=id}configReady=true;render()}catch(e){console.warn('Preferenze condivise non disponibili',e);}}
async function persistShared(){const payload={rooms:roomAssignments,widgets:widgetConfigs,...Object.fromEntries(SHARED_FIELDS.filter(k=>!['rooms','widgets'].includes(k)).map(k=>[k,prefs[k]]).filter(([k,v])=>v!==undefined))};const res=await fetch('api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!res.ok)throw Error((await res.json()).error||'Salvataggio non riuscito');configReady=true;}
function deviceLabel(id){return S(id)?.attributes?.friendly_name||id}
function roomEntities(room){if(Array.isArray(roomAssignments[room]))return roomAssignments[room];const fallback={'Salotto':['light.salotto','light.4d_f59b','cover.shellyswitch25_68e7a1'],'Cucina':['light.luce_terrazza_cucina','cover.shellyplus2pm_fcb46726ef20_cover_0'],'Camera':['light.abatjour','cover.shellyplus2pm_e86beae91850_cover_0'],'Bagno':['light.bagno'],'Garage':['light.shelly1_349454741da8'],'Terrazza':['light.luce_terrazza_letto','light.luce_terrazza_parco']};return fallback[room]||[];}
function inventoryCard(id){const domain=id.split('.')[0],state=val(id),name=deviceLabel(id);let actions='';if(domain==='light'||domain==='switch')actions=panelAction(isOn(id)?'Spegni':'Accendi',domain,isOn(id)?'turn_off':'turn_on',id);else if(domain==='cover')actions=panelAction('Apri','cover','open_cover',id)+panelAction('Stop','cover','stop_cover',id)+panelAction('Chiudi','cover','close_cover',id);else if(domain==='lock')actions='<button type="button" data-inventory-detail="door">Gestisci</button>';else if(domain==='climate')actions='<button type="button" data-inventory-detail="climate">Gestisci</button>';else if(domain==='alarm_control_panel')actions='<button type="button" data-inventory-alarm>Gestisci</button>';return `<div class="inventory-device"><div><strong>${esc(name)}</strong><small>${esc(id)} · ${esc(state)}</small></div><div class="detail-commands">${actions}</div></div>`;}
function roomManager(){return `<div class="prefs-card"><h2>Associa dispositivi alle stanze</h2><p>Modifiche condivise tra PC e iPhone. Ogni entità può essere assegnata tramite ricerca.</p><div class="room-editor">${[...new Set([...DEFAULT_ROOMS,...Object.keys(roomAssignments)])].map(room=>`<div class="room-editor-group"><h3>${esc(room)}</h3><div class="room-editor-items">${roomEntities(room).map(id=>`<div><span>${esc(deviceLabel(id))}</span><button data-room-remove="${esc(room)}" data-remove-id="${esc(id)}">✕</button></div>`).join('')}</div><div class="room-picker"><input type="text" list="entity-choices" placeholder="Cerca ID o scegli entità" data-room-input="${esc(room)}"><button data-room-add="${esc(room)}">Aggiungi</button></div></div>`).join('')}</div></div>`;}
function widgetCard(w,i){const id=w.entity||'',a=S(id)?.attributes||{},value=id?fmt(id):'—',type=w.type||'entity';const extra=type==='proxmox'?'🖥️':type==='ups'?'🔋':type==='energy'?'⚡':type==='network'?'📡':type==='zigbee'?'🔗':type==='kodi'?'🎬':'◈';return `<div class="studio-widget animated-widget widget-span-${w.span||1}" data-widget-index="${i}" draggable="${view==='impostazioni'}"><span>${extra}</span><small>${esc(type)}</small><h3>${esc(w.title||deviceLabel(id))}</h3><div class="studio-value">${esc(value)}</div><p>${esc(id?val(id):'Associa un sensore')}</p><div class="widget-footer"><span>${esc(a.friendly_name||'Home Assistant')}</span>${view==='impostazioni'?`<button data-widget-resize="${i}">⇔ ${w.span||1}×</button><button data-widget-remove="${i}">Rimuovi</button>`:''}</div></div>`;}
function widgetsBlock(){return widgetConfigs.length?`<div class="widget-studio-grid">${widgetConfigs.map(widgetCard).join('')}</div>`:''}
function widgetManager(){return `<div class="prefs-card"><h2>Widget Studio</h2><p>Crea card collegate a sensori reali. Le preferenze si sincronizzano tramite l'App.</p><div class="widget-creator"><label>Modulo<select id="new-widget-type">${['entity','proxmox','ups','energy','network','zigbee','kodi'].map(t=>`<option value="${t}">${t}</option>`).join('')}</select></label><label>Titolo<input id="new-widget-title" placeholder="Es. Host Proxmox"></label><label>Entità<input id="new-widget-entity" list="entity-choices" placeholder="sensor..."></label><button data-widget-add>Aggiungi widget</button></div>${widgetsBlock()}</div>`;}
function diagnostics(){const categories=[['🖥️','Proxmox',['sensor.node_proxmox_cpu_usata','sensor.proxmox_cpu_temp','binary_sensor.node_proxmox_stato']],['🔋','UPS',['sensor.apcups_carica_batterie']],['⚡','Energia',[E.power,'sensor.pun_prezzo_fascia_corrente']],['📶','Rete',['switch.pi_hole']],['📡','Zigbee',['sensor.telecomando_ikea_battery']]];return `<div class="diagnostic-grid">${categories.map(([icon,title,ids])=>`<section class="diagnostic-card"><div class="diagnostic-icon">${icon}</div><h3>${title}</h3>${ids.map(id=>`<div class="detail-row"><span>${esc(deviceLabel(id))}</span><strong>${esc(fmt(id))}</strong></div>`).join('')}</section>`).join('')}</div>`;}

let bridgeData={status:'loading',root:'film',path:null,page:0,items:[],title:'Film',query:'',favourites:false};
async function bridgeFetch(route,data){const opts=data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{cache:'no-store'};const r=await fetch('api/bridge/'+route,opts);const j=await r.json();if(!r.ok)throw Error(j.error||'Bridge non raggiungibile');return j}
function bridgeRows(data){return Array.isArray(data)?data:Array.isArray(data?.items)?data.items:Array.isArray(data?.entries)?data.entries:Array.isArray(data?.results)?data.results:[]}
function bridgeInfo(item){return {id:item.id||item.key||'',title:item.title||item.label||item.name||'Senza titolo',directory:!!(item.is_folder||item.is_directory||item.type==='directory'||item.kind==='directory'||item.folder)}}
function kodiRemote(){return `<div class="kodi-remote kodi-real"><div class="kodi-title"><h3>🎬 Kodi Smart Bridge</h3><span class="bridge-indicator">${esc(bridgeData.status==='ready'?'● Collegato':bridgeData.status==='loading'?'◌ Connessione…':'○ Non collegato')}</span></div>${bridgeData.status==='error'?'<p>Configura indirizzo e token del bridge nelle opzioni private dell’App Aveniq. Il catalogo e i preferiti sono disponibili soltanto con il bridge operativo.</p>':''}<div class="bridge-tabs">${[['film','Film'],['series','Serie TV'],['tv','Live TV'],['radio','Radio'],['movies','VOD'],['favourites','Preferiti']].map(([id,label])=>`<button data-bridge-root="${id}" class="${bridgeData.root===id?'selected':''}">${label}</button>`).join('')}</div><div class="bridge-search"><input id="bridge-search-input" placeholder="Cerca nei contenuti" value="${esc(bridgeData.query)}"><button data-bridge-search>Cerca</button><button data-bridge-back>Indietro</button></div><div class="bridge-content">${bridgeData.items.length?bridgeData.items.map((item,index)=>{const x=bridgeInfo(item);return `<div class="bridge-item"><div><strong>${esc(x.title)}</strong><small>${x.directory?'Cartella':'Contenuto'}</small></div><div class="bridge-actions"><button data-bridge-item="${index}">${x.directory?'Apri':'▶ Riproduci'}</button><button data-bridge-fav="${index}" aria-label="Aggiungi ai preferiti">☆</button></div></div>`}).join(''):'<p class="bridge-empty">Nessun elemento caricato. Seleziona una categoria.</p>'}</div><div class="bridge-pagination"><button data-bridge-prev ${bridgeData.page===0?'disabled':''}>← Precedenti</button><span>Pagina ${bridgeData.page+1}</span><button data-bridge-next>Successivi →</button></div></div>`}
async function bridgeBrowse(root='film',id=null,page=0,query=''){bridgeData={...bridgeData,status:'loading',root,path:id,page,query,items:[]};if(view==='media')render();try{const r=root==='favourites'?await bridgeFetch('favourites'):await bridgeFetch('browse',{root,id,page,page_size:24,search:query});bridgeData.items=bridgeRows(r);bridgeData.status='ready';if(view==='media')render()}catch(e){bridgeData.status='error';toast(e.message);if(view==='media')render()}}
function wireBridge(){document.querySelectorAll('[data-bridge-root]').forEach(b=>b.addEventListener('click',()=>bridgeBrowse(b.dataset.bridgeRoot)));document.querySelector('[data-bridge-search]')?.addEventListener('click',()=>bridgeBrowse(bridgeData.root,null,0,document.querySelector('#bridge-search-input')?.value||''));document.querySelector('[data-bridge-back]')?.addEventListener('click',()=>bridgeBrowse(bridgeData.root));document.querySelector('[data-bridge-next]')?.addEventListener('click',()=>bridgeBrowse(bridgeData.root,bridgeData.path,bridgeData.page+1,bridgeData.query));document.querySelector('[data-bridge-prev]')?.addEventListener('click',()=>bridgeBrowse(bridgeData.root,bridgeData.path,Math.max(0,bridgeData.page-1),bridgeData.query));document.querySelectorAll('[data-bridge-item]').forEach(b=>b.addEventListener('click',async()=>{const item=bridgeData.items[Number(b.dataset.bridgeItem)],data=bridgeInfo(item);if(!data.id)return toast('Elemento non disponibile');if(data.directory)return bridgeBrowse(bridgeData.root,data.id);try{await bridgeFetch('play',{id:data.id});toast('Riproduzione inviata a Kodi')}catch(e){toast(e.message)}}));document.querySelectorAll('[data-bridge-fav]').forEach(b=>b.addEventListener('click',async()=>{const item=bridgeData.items[Number(b.dataset.bridgeFav)],data=bridgeInfo(item);if(!data.id)return;try{await bridgeFetch('favourite',{id:data.id,title:data.title,poster:item.poster||''});toast('Aggiunto ai preferiti')}catch(e){toast(e.message)}}))}

function wireExtension(){if(view==='media')wireBridge();let dragged=null;document.querySelectorAll('.studio-widget[draggable=true]').forEach(el=>{el.addEventListener('dragstart',e=>{dragged=Number(el.dataset.widgetIndex);e.dataTransfer.effectAllowed='move';});el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',async e=>{e.preventDefault();const to=Number(el.dataset.widgetIndex);if(dragged===null||dragged===to)return;const old=widgetConfigs.slice(),moved=widgetConfigs.splice(dragged,1)[0];widgetConfigs.splice(to,0,moved);try{await persistShared();render()}catch(err){widgetConfigs=old;toast(err.message)}})});document.querySelectorAll('[data-widget-resize]').forEach(b=>b.addEventListener('click',async()=>{const i=Number(b.dataset.widgetResize),old=widgetConfigs[i].span||1;widgetConfigs[i].span=old===3?1:old+1;try{await persistShared();render()}catch(err){widgetConfigs[i].span=old;toast(err.message)}}));document.querySelectorAll('[data-kodi-key]').forEach(b=>b.addEventListener('click',()=>detailCall('kodi','call_method',b.dataset.kodiId,{method:b.dataset.kodiKey})));document.querySelectorAll('[data-inventory-detail]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.inventoryDetail)));document.querySelectorAll('[data-inventory-alarm]').forEach(b=>b.addEventListener('click',openAlarm));document.querySelectorAll('[data-room-add]').forEach(b=>b.addEventListener('click',async()=>{const room=b.dataset.roomAdd, input=document.querySelector('[data-room-input="'+room+'"]'),id=input?.value.trim();if(!id||!states[id])return toast('Seleziona un’entità esistente');roomAssignments[room]=[...new Set([...roomEntities(room),id])];try{await persistShared();render()}catch(e){toast(e.message)}}));document.querySelectorAll('[data-room-remove]').forEach(b=>b.addEventListener('click',async()=>{const room=b.dataset.roomRemove;roomAssignments[room]=roomEntities(room).filter(id=>id!==b.dataset.removeId);try{await persistShared();render()}catch(e){toast(e.message)}}));document.querySelector('[data-widget-add]')?.addEventListener('click',async()=>{const type=document.querySelector('#new-widget-type').value,title=document.querySelector('#new-widget-title').value.trim(),entity=document.querySelector('#new-widget-entity').value.trim();if(!states[entity])return toast('Seleziona un’entità reale');widgetConfigs.push({type,title:title||deviceLabel(entity),entity});try{await persistShared();render()}catch(e){widgetConfigs.pop();toast(e.message)}});document.querySelectorAll('[data-widget-remove]').forEach(b=>b.addEventListener('click',async()=>{const index=Number(b.dataset.widgetRemove),old=widgetConfigs.slice();widgetConfigs.splice(index,1);try{await persistShared();render()}catch(e){widgetConfigs=old;toast(e.message)}}));}

function homeRooms(){return `<div class="room-grid">${[...new Set([...DEFAULT_ROOMS,...Object.keys(roomAssignments)])].map(room=>`<button class="room-card" data-room="${esc(room)}"><span class="room-icon">⌂</span><strong>${esc(room)}</strong><small>${roomEntities(room).length} dispositivi associati</small><span class="room-status">Apri stanza ↗</span></button>`).join('')}</div>`;}

function roomsPage(){return `${section('Ambienti','Controlli raggruppati per stanza')}${homeRooms()}${section('Dispositivi','Elenco completo')}${Object.keys(states).filter(id=>['light','cover','climate','lock','switch','vacuum','media_player'].includes(id.split('.')[0])).length} entità controllabili disponibili`;}
function settingsPage(){const mappings=[['weather','Meteo'],['temp','Temperatura interna'],['humid','Umidità interna'],['outtemp','Temperatura esterna'],['outhumid','Umidità esterna'],['power','Potenza elettrica'],['alarm','Alarmo'],['door','Serratura Nuki'],['lights','Contatore luci'],['thermo','Termostato'],['ac','Climatizzatore'],['vacuum','Aspirapolvere']];return `<section class="prefs-card"><h2>Personalizza Aveniq</h2><p>Tutte le preferenze grafiche rimangono in questo browser. Non modificano Home Assistant.</p><div class="settings-form"><label>Tema<select data-pref="theme"><option value="light" ${prefs.theme==='light'?'selected':''}>Chiaro</option><option value="dark" ${prefs.theme==='dark'?'selected':''}>Notte</option></select></label><label><input type="checkbox" data-pref="compact" ${prefs.compact?'checked':''}> Vista compatta</label><label><input type="checkbox" data-pref="showHero" ${prefs.showHero?'checked':''}> Mostra intestazione panoramica</label><label><input type="checkbox" data-pref="showStatus" ${prefs.showStatus?'checked':''}> Mostra stato della casa</label><label><input type="checkbox" data-pref="showWidgets" ${prefs.showWidgets?'checked':''}> Mostra widget</label><label><input type="checkbox" data-pref="showQuick" ${prefs.showQuick?'checked':''}> Mostra controlli rapidi</label></div></section><section class="prefs-card"><h2>Associazione entità</h2><p>Scegli le entità reali presenti su Home Assistant. Gli ID devono corrispondere esattamente.</p><div class="settings-mapping">${mappings.map(([key,label])=>`<label>${esc(label)}<input data-entity-key="${key}" list="entity-choices" autocomplete="off" value="${esc(E[key]||'')}" spellcheck="false"></label>`).join('')}</div><datalist id="entity-choices">${Object.keys(states).slice(0,1500).map(id=>`<option value="${esc(id)}"></option>`).join('')}</datalist>${roomManager()}${widgetManager()}<div class="settings-actions"><button data-save-settings>Salva preferenze</button><button data-export-settings>Esporta JSON</button><button data-reset-settings>Ripristina</button></div><p class="prefs-note">Non vengono salvati codici Alarmo, token o password. Le impostazioni sono locali al dispositivo.</p></section>`;}
function setPreferences(){document.body.classList.toggle('aveniq-dark',prefs.theme==='dark');document.body.classList.toggle('aveniq-compact',!!prefs.compact)}
function bindSettings(){document.querySelector('[data-save-settings]')?.addEventListener('click',()=>{document.querySelectorAll('[data-pref]').forEach(el=>{prefs[el.dataset.pref]=el.type==='checkbox'?el.checked:el.value});let bad=false;document.querySelectorAll('[data-entity-key]').forEach(el=>{const id=el.value.trim();if(!/^[a-z_]+\.[a-z0-9_]+$/.test(id)){bad=true;return}prefs.entityMap[el.dataset.entityKey]=id;E[el.dataset.entityKey]=id});if(bad)return toast('Controlla gli ID delle entità');localStorage.setItem(PREF_KEY,JSON.stringify(prefs));persistShared().then(()=>toast('Preferenze sincronizzate')).catch(e=>toast('Salvataggio condiviso non riuscito: '+e.message));setPreferences();render()});document.querySelector('[data-reset-settings]')?.addEventListener('click',()=>{if(!confirm('Ripristinare le preferenze di Aveniq?'))return;localStorage.removeItem(PREF_KEY);location.reload()});document.querySelector('[data-export-settings]')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(prefs,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aveniq-preferenze.json';a.click();URL.revokeObjectURL(url)});}
function openRoom(name){detailPanel='room';document.querySelector('.detail-overlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="detail-overlay"><div class="detail-scrim" data-room-close></div><section class="detail-panel" role="dialog" aria-modal="true" aria-label="Ambiente ${esc(name)}"><div class="detail-header"><h2>${esc(name)}</h2><button class="detail-x" data-room-close>✕</button></div><div class="detail-body"><div class="detail-group">${roomEntities(name).map(inventoryCard).join('')||'Nessun dispositivo associato'}</div></div></section></div>`);document.querySelectorAll('[data-room-close]').forEach(b=>b.addEventListener('click',()=>{detailPanel=null;document.querySelector('.detail-overlay')?.remove()}));document.querySelectorAll('.detail-overlay [data-d-action]').forEach(b=>b.addEventListener('click',()=>detailCall(b.dataset.domain,b.dataset.service,b.dataset.id,{})));document.querySelectorAll('.detail-overlay [data-inventory-detail]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.inventoryDetail)));document.querySelector('.detail-overlay [data-inventory-alarm]')?.addEventListener('click',openAlarm)}

function render(){setPreferences();document.querySelector('#app').innerHTML=`<div class="shell"><aside><div class="brand">aven<span>iq</span>.</div><nav class="nav">${nav()}</nav><div class="foot">AVENIQ · v0.7.0<br>Home Assistant App</div></aside><main><div class="top"><div><div class="eyebrow">Smart living dashboard</div><h1>${NAV.find(x=>x[0]===view)?.[2]||'Panoramica'}</h1></div><span class="online ${connected?'':'offline'}">● ${connected?'Connesso':'Non connesso'}</span></div>${loading?'<div class="banner">Caricamento stati Home Assistant…</div>':''}${({home,clima:climate,luci:lights,sicurezza:security,tende:covers,media,sistema:system,ambienti:roomsPage,impostazioni:settingsPage}[view]||home)()}<div class="foot" style="margin-top:22px;color:#a2adba;font-size:12px">Aveniq 0.7 · Aggiornamento dati ogni 8 secondi</div></main><nav class="bottomnav">${NAV.map(([key,icon,title])=>`<button data-view="${key}" class="${view===key?'active':''}"><b>${icon}</b>${title}</button>`).join('')}</nav></div>`;document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render();window.scrollTo(0,0)}));document.querySelectorAll('[data-domain]').forEach(b=>b.addEventListener('click',()=>call(b)));document.querySelectorAll('[data-open-alarm]').forEach(b=>b.addEventListener('click',openAlarm));document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.panel)));document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>openRoom(b.dataset.room)));if(view==='impostazioni')bindSettings();wireExtension();}
function toast(text){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.textContent=text;document.body.appendChild(t);setTimeout(()=>t.remove(),3500)}
async function call(b){if(requestRunning)return;requestRunning=true;b.disabled=true;try{const res=await fetch('api/service',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({domain:b.dataset.domain,service:b.dataset.service,entity_id:b.dataset.id,data:JSON.parse(decodeURIComponent(b.dataset.extra||'%7B%7D'))})});if(!res.ok)throw Error((await res.json()).error||'Errore');toast('Comando inviato');await refresh()}catch(e){toast('Errore: '+e.message)}finally{requestRunning=false;b.disabled=false}}
async function refresh(){try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),6500);const res=await fetch('api/states',{cache:'no-store',signal:controller.signal});clearTimeout(timeout);if(!res.ok)throw Error('HA non disponibile');const response=await res.json();states=Object.fromEntries(response.states.map(s=>[s.entity_id,s]));connected=true}catch(e){connected=false}loading=false;render()}
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelector('.alarm-backdrop')?.remove();closeDetail()}});
/* v0.2.0 — interactive detail panels */
const panelAction=(label,domain,service,id,data={})=>`<button class="detail-action" data-d-action data-domain="${domain}" data-service="${service}" data-id="${esc(id)}" data-extra="${encodeURIComponent(JSON.stringify(data))}" ${!valid(id)?'disabled':''}>${esc(label)}</button>`;
const detailRow=(title,value)=>`<div class="detail-row"><span>${esc(title)}</span><strong>${esc(value)}</strong></div>`;
const detailDevice=([icon,name,id])=>`<div class="detail-device"><span>${icon}</span><div><b>${esc(name)}</b><small>${esc(val(id))}</small></div><div class="detail-commands">${id.startsWith('light.')?panelAction(isOn(id)?'Spegni':'Accendi','light',isOn(id)?'turn_off':'turn_on',id):id.startsWith('cover.')?panelAction('Apri','cover','open_cover',id)+panelAction('Stop','cover','stop_cover',id)+panelAction('Chiudi','cover','close_cover',id):''}</div></div>`;
const activeLights=()=>GROUPS.luci.filter(d=>valid(d[2])&&isOn(d[2])).length;

/* Premium Climate — SVG thermostat and capabilities-driven controls */
const climateName=(v)=>({off:'Spento',heat:'Riscaldamento',cool:'Raffrescamento',auto:'Automatico',dry:'Deumidificazione',fan_only:'Ventilazione',heat_cool:'Caldo/Freddo'})[v]||v;
const climateTarget=(id)=>{const n=Number(S(id)?.attributes?.temperature);return Number.isFinite(n)?n:null};
const climateRange=(id)=>{const a=S(id)?.attributes||{};const min=Number.isFinite(Number(a.min_temp))?Number(a.min_temp):7,max=Number.isFinite(Number(a.max_temp))?Number(a.max_temp):30;const step=Number(a.target_temp_step)||0.5;return {min,max:max>min?max:min+10,step:step>0?step:0.5}};
const dialPoint=(deg,r)=>{const t=deg*Math.PI/180;return [150+Math.cos(t)*r,150+Math.sin(t)*r]};
const dialArc=(start,end,r)=>{const [x,y]=dialPoint(start,r),[a,b]=dialPoint(end,r);return 'M '+x.toFixed(2)+' '+y.toFixed(2)+' A '+r+' '+r+' 0 '+(Math.abs(end-start)>180?1:0)+' 1 '+a.toFixed(2)+' '+b.toFixed(2)};
function climatePremium(id,name,theme){const s=S(id),a=s?.attributes||{},r=climateRange(id),target=climateTarget(id),current=Number(a.current_temperature),working=a.hvac_action==='heating'||a.hvac_action==='cooling';const valTarget=target??r.min,p=Math.min(1,Math.max(0,(valTarget-r.min)/(r.max-r.min))),angle=135+p*270,pt=dialPoint(angle,108);
const modes=(a.hvac_modes||[]).filter(v=>['off','heat','cool','dry','fan_only','auto','heat_cool'].includes(v));
const opts=(title,values,service)=>Array.isArray(values)&&values.length?`<div class="climate-option"><span>${title}</span><div class="climate-mode-list">${values.map(v=>`<button type="button" class="${(service==='set_fan_mode'?a.fan_mode:a.swing_mode)===v?'selected':''}" data-climate-option="${service}" data-climate-id="${esc(id)}" data-climate-value="${esc(v)}">${esc(v)}</button>`).join('')}</div></div>`:'';
return `<section class="climate-premium ${theme}" data-climate-zone="${esc(id)}"><div class="climate-premium-header"><div><small>${theme==='warm'?'RISCALDAMENTO DOMESTICO':'CLIMATIZZAZIONE'}</small><h3>${name}</h3></div><span class="climate-state ${working?'running':''}">${esc(working?'In funzione':climateName(val(id)))}</span></div>
<div class="climate-dial" data-dial-id="${esc(id)}" data-min="${r.min}" data-max="${r.max}" data-step="${r.step}" role="group" aria-label="Imposta temperatura ${name}">
<svg viewBox="0 0 300 300" aria-hidden="true"><defs><linearGradient id="grad-${theme}" x1="0" y1="1" x2="1" y2="0"><stop stop-color="${theme==='warm'?'#ffbd9c':'#64d8f2'}"/><stop offset="1" stop-color="${theme==='warm'?'#f27942':'#1981cb'}"/></linearGradient></defs>
<path d="${dialArc(135,405,108)}" fill="none" stroke="#e5eaf1" stroke-width="17" stroke-linecap="round"/>
<path class="climate-progress" d="${dialArc(135,Math.max(135,angle),108)}" fill="none" stroke="url(#grad-${theme})" stroke-width="17" stroke-linecap="round"/>
<circle class="climate-thumb" cx="${pt[0]}" cy="${pt[1]}" r="11" fill="white" stroke="${theme==='warm'?'#f27942':'#1981cb'}" stroke-width="4"/></svg>
<div class="climate-dial-center"><span>Temperatura desiderata</span><strong data-dial-value>${target===null?'—':esc(target.toFixed(1))}<small>°C</small></strong><em>${Number.isFinite(current)?'Ambiente '+current.toFixed(1)+'°C':'Temperatura ambiente non disponibile'}</em></div>
</div><div class="climate-dial-buttons"><button type="button" data-dial-step="-1" data-dial-target="${esc(id)}" aria-label="Riduci temperatura">−</button><span>${r.min}° — ${r.max}°</span><button type="button" data-dial-step="1" data-dial-target="${esc(id)}" aria-label="Aumenta temperatura">+</button></div>
<div class="climate-mode-list">${modes.map(m=>`<button type="button" data-climate-mode="${esc(m)}" data-climate-id="${esc(id)}" class="${val(id)===m?'selected':''}">${esc(climateName(m))}</button>`).join('')}</div>
${opts('Velocità ventola',a.fan_modes,'set_fan_mode')}${opts('Oscillazione',a.swing_modes,'set_swing_mode')}
<div class="climate-info"><span>Stato HVAC <b>${esc(a.hvac_action||'—')}</b></span><span>Setpoint <b>${target===null?'—':target.toFixed(1)+' °C'}</b></span></div>
<p class="climate-hint">Trascina la ghiera o usa + / −. Il nuovo setpoint viene inviato quando rilasci.</p></section>`;}
function setDialVisual(zone,v){const dial=zone.querySelector('.climate-dial');if(!dial)return;const min=Number(dial.dataset.min),max=Number(dial.dataset.max),step=Number(dial.dataset.step),value=Math.max(min,Math.min(max,Math.round(v/step)*step));const angle=135+(value-min)/(max-min)*270,xy=dialPoint(angle,108);zone.querySelector('[data-dial-value]').innerHTML=value.toFixed(1)+'<small>°C</small>';zone.querySelector('.climate-progress').setAttribute('d',dialArc(135,Math.max(135,angle),108));const thumb=zone.querySelector('.climate-thumb');thumb.setAttribute('cx',xy[0]);thumb.setAttribute('cy',xy[1]);dial.dataset.pending=String(value);}
function climatePointer(event,dial){const svg=dial.querySelector('svg'),rect=svg.getBoundingClientRect();const x=(event.clientX-rect.left)/rect.width*300-150,y=(event.clientY-rect.top)/rect.height*300-150;const deg=(Math.atan2(y,x)*180/Math.PI+360)%360;let sweep=(deg-135+360)%360;if(sweep>270)sweep=(sweep-270<45)?270:0;const min=Number(dial.dataset.min),max=Number(dial.dataset.max);setDialVisual(dial.closest('.climate-premium'),min+sweep/270*(max-min));}
function wireClimate(){document.querySelectorAll('[data-climate-mode]').forEach(el=>el.addEventListener('click',()=>detailCall('climate','set_hvac_mode',el.dataset.climateId,{hvac_mode:el.dataset.climateMode})));document.querySelectorAll('[data-climate-option]').forEach(el=>el.addEventListener('click',()=>detailCall('climate',el.dataset.climateOption,el.dataset.climateId,{[el.dataset.climateOption==='set_fan_mode'?'fan_mode':'swing_mode']:el.dataset.climateValue})));
document.querySelectorAll('[data-dial-step]').forEach(el=>el.addEventListener('click',()=>{const zone=document.querySelector('[data-climate-zone="'+el.dataset.dialTarget+'"]'),dial=zone?.querySelector('.climate-dial');if(!dial)return;const n=Number(dial.dataset.pending??climateTarget(el.dataset.dialTarget)??21)+Number(el.dataset.dialStep)*Number(dial.dataset.step);setDialVisual(zone,n);detailCall('climate','set_temperature',el.dataset.dialTarget,{temperature:Number(dial.dataset.pending)})}));
document.querySelectorAll('.climate-dial').forEach(dial=>{let active=false;dial.addEventListener('pointerdown',ev=>{if(!valid(dial.dataset.dialId))return;active=true;dial.setPointerCapture(ev.pointerId);climatePointer(ev,dial)});dial.addEventListener('pointermove',ev=>{if(active)climatePointer(ev,dial)});dial.addEventListener('pointerup',()=>{if(!active)return;active=false;detailCall('climate','set_temperature',dial.dataset.dialId,{temperature:Number(dial.dataset.pending)})});dial.addEventListener('pointercancel',()=>{active=false})})}

const details={
 climate:()=>`<p class="detail-lead">Due zone, due controlli dedicati.</p>${climatePremium(E.thermo,'Netatmo','warm')}${climatePremium(E.ac,'Daikin','cool')}<div class="detail-stats">${detailRow('Umidità interna',fmt(E.humid))}${detailRow('Temperatura esterna',fmt(E.outtemp))}${detailRow('Umidità esterna',fmt(E.outhumid))}${detailRow('Caldaia oggi',fmt('sensor.netatmo_salone_durata_accensione_24h'))}</div>`,
 lights:()=>`<p class="detail-lead">${activeLights()} luci accese</p><div class="detail-group">${GROUPS.luci.map(detailDevice).join('')}</div><div class="detail-group"><h3>Dimmer e colori</h3>${GROUPS.luci.filter(d=>valid(d[2])&&S(d[2])?.attributes?.supported_color_modes?.some(x=>x!=='onoff')).map(d=>`<div class="detail-range"><b>${esc(d[1])}</b><label>Luminosità <input data-bright="${esc(d[2])}" type="range" min="1" max="100" value="${Math.round((S(d[2])?.attributes?.brightness||255)/255*100)}"></label>${S(d[2])?.attributes?.supported_color_modes?.some(x=>['rgb','rgbw','rgbww','hs','xy'].includes(x))?`<label>Colore <input data-color="${esc(d[2])}" type="color" value="#00a5e5"></label>`:''}</div>`).join('')||'<p>Nessuna lampada dimmerabile disponibile.</p>'}</div>`,
 covers:()=>`<p class="detail-lead">Controllo tende Shelly</p><div class="detail-group">${GROUPS.tende.map(d=>`<div class="detail-device"><span>▤</span><div><b>${esc(d[1])}</b><small>${esc(val(d[2]))} ${S(d[2])?.attributes?.current_position!=null?'· '+esc(S(d[2]).attributes.current_position)+'%':''}</small></div><div class="detail-commands">${panelAction('↑','cover','open_cover',d[2])}${panelAction('■','cover','stop_cover',d[2])}${panelAction('↓','cover','close_cover',d[2])}</div></div>${valid(d[2])&&S(d[2])?.attributes?.supported_features&4?`<div class="detail-range"><label>Posizione <input data-cover-pos="${esc(d[2])}" type="range" min="0" max="100" value="${esc(S(d[2])?.attributes?.current_position??0)}"></label></div>`:''}`).join('')}</div>`,
 batteries:()=>`<p class="detail-lead">Livelli di carica in ordine crescente</p><div class="detail-group">${GROUPS.sistema.filter(d=>valid(d[2])).sort((a,b)=>Number(val(a[2]))-Number(val(b[2]))).map(d=>`<div class="battery-detail"><span>${esc(d[1])}</span><b>${fmt(d[2])}</b><div class="battery-track"><i style="width:${pct(d[2])}%;background:${pct(d[2])<=25?'#f07d65':'#36ba90'}"></i></div></div>`).join('')}</div>`,
 contacts:()=>`<p class="detail-lead">Contatti porte e finestre</p><div class="detail-group">${GROUPS.sicurezza.map(d=>detailRow(d[1],valid(d[2])?(isOn(d[2])?'Aperto':'Chiuso'):'Non disponibile')).join('')}</div>`,
 door:()=>`<p class="detail-lead">Controllo serratura Nuki</p><div class="detail-group">${detailRow('Porta ingresso',val(E.door))}${detailRow('Batteria',fmt('sensor.porta_ingresso_battery_2'))}<div class="detail-buttons">${panelAction('🔒 Blocca','lock','lock',E.door)}${panelAction('🔓 Sblocca','lock','unlock',E.door)}${(Number(S(E.door)?.attributes?.supported_features||0)&1)?panelAction('🚪 Apri porta','lock','open',E.door):'<span class="detail-hint">Apertura porta non dichiarata come supportata da Nuki.</span>'}</div><p class="detail-hint">Ogni operazione richiede una conferma. Apri porta aziona lo scrocco quando supportato; Sblocca non apre necessariamente la porta.</p></div>`,
 energy:()=>`<p class="detail-lead">Consumi elettrici Shelly</p><div class="detail-group">${detailRow('Potenza istantanea',fmt(E.power))}${detailRow('Fascia corrente',val('sensor.pun_fascia_corrente'))}${detailRow('Prezzo energia',fmt('sensor.pun_prezzo_fascia_corrente'))}</div><div class="detail-group"><h3>Andamento ultime 24 ore</h3><div id="history-chart" class="history-chart">Caricamento storico…</div></div>`
};
let detailPanel=null, detailRequest=false, detailHistory=[];
function openDetail(key){detailPanel=key;paintDetail();if(key==='energy')loadHistory();}
function closeDetail(){detailPanel=null;document.querySelector('.detail-overlay')?.remove();}
function paintDetail(){if(!detailPanel)return;document.querySelector('.detail-overlay')?.remove();const names={climate:'Clima',lights:'Illuminazione',covers:'Tende',batteries:'Batterie',contacts:'Aperture',door:'Serratura',energy:'Energia'};document.body.insertAdjacentHTML('beforeend',`<div class="detail-overlay"><div class="detail-scrim" data-detail-close></div><section class="detail-panel" role="dialog" aria-modal="true" aria-labelledby="detail-title"><div class="detail-header"><div><span class="eyebrow">AVENIQ · CONTROLLI</span><h2 id="detail-title">${esc(names[detailPanel])}</h2></div><button class="detail-x" data-detail-close aria-label="Chiudi">✕</button></div><div class="detail-body">${details[detailPanel]?.()||''}</div><div class="detail-status" aria-live="polite"></div></section></div>`);document.querySelectorAll('[data-detail-close]').forEach(x=>x.addEventListener('click',closeDetail));document.querySelectorAll('[data-d-action]').forEach(x=>x.addEventListener('click',()=>detailCall(x.dataset.domain,x.dataset.service,x.dataset.id,JSON.parse(decodeURIComponent(x.dataset.extra||'%7B%7D')))));document.querySelectorAll('[data-set-temp]').forEach(x=>x.addEventListener('click',()=>{const input=document.querySelector('[data-temp-id="'+x.dataset.setTemp+'"]'),v=Number(input.value);if(!Number.isFinite(v)||v<12||v>32)return toast('Temperatura non valida');detailCall('climate','set_temperature',x.dataset.setTemp,{temperature:v})}));document.querySelectorAll('[data-bright]').forEach(x=>x.addEventListener('change',()=>detailCall('light','turn_on',x.dataset.bright,{brightness_pct:Number(x.value)})));document.querySelectorAll('[data-color]').forEach(x=>x.addEventListener('change',()=>{const c=x.value;detailCall('light','turn_on',x.dataset.color,{rgb_color:[1,3,5].map(i=>parseInt(c.slice(i,i+2),16))})}));document.querySelectorAll('[data-cover-pos]').forEach(x=>x.addEventListener('change',()=>detailCall('cover','set_cover_position',x.dataset.coverPos,{position:Number(x.value)})));if(detailPanel==='energy'&&detailHistory.length)drawHistory();if(detailPanel==='climate')wireClimate();}
async function detailCall(domain,service,entity_id,data){if(detailRequest)return;if(domain==='lock'&&!window.confirm(({lock:'Confermi il blocco della porta?',unlock:'Confermi lo sblocco della serratura?',open:'Confermi l’apertura della porta? Verifica che sia sicuro aprirla.'})[service]||'Confermi il comando?'))return;detailRequest=true;const status=document.querySelector('.detail-status');if(status)status.textContent='Invio comando…';try{const res=await fetch('api/service',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({domain,service,entity_id,data})});const d=await res.json();if(!res.ok)throw Error(d.error||'Comando fallito');if(status)status.textContent='Comando inviato';await refresh();if(detailPanel)paintDetail()}catch(e){toast('Errore: '+e.message);if(status)status.textContent='Errore: '+e.message}finally{detailRequest=false}}
async function loadHistory(){detailHistory=[];try{const r=await fetch('api/history?entity_id='+encodeURIComponent(E.power));if(!r.ok)throw Error('Storico non disponibile');const d=await r.json();detailHistory=(d.points||[]).filter(x=>Number.isFinite(x.value))}catch(e){detailHistory=[]}drawHistory()}
function drawHistory(){const el=document.querySelector('#history-chart');if(!el)return;if(!detailHistory.length){el.textContent='Nessun dato storico disponibile';return}const data=detailHistory;const max=Math.max(...data.map(x=>x.value),0.001);const min=Math.min(...data.map(x=>x.value),0);const pts=data.map((d,i)=>`${10+(i/Math.max(1,data.length-1))*660},${190-(d.value-min)/(max-min||1)*175}`).join(' ');el.innerHTML=`<svg viewBox="0 0 680 220" role="img" aria-label="Storico consumi ultime 24 ore"><path d="M10 190 H670" stroke="#dbe7ef"/><polyline points="${pts}" fill="none" stroke="#07a8ba" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="history-legend"><span>24 ore fa</span><span>Max ${max.toFixed(2)} ${esc(unit(E.power))}</span><span>Adesso</span></div>`}

render();loadSharedConfig();refresh();bridgeBrowse('film');if('EventSource' in window){const stream=new EventSource('api/events');stream.addEventListener('states',event=>{try{const data=JSON.parse(event.data);states=Object.fromEntries(data.states.map(s=>[s.entity_id,s]));connected=true;loading=false;if(!requestRunning&&!detailRequest&&!document.querySelector('.detail-overlay,.alarm-backdrop')&&view!=='impostazioni')render()}catch(e){console.warn(e)}});stream.addEventListener('config',event=>{try{const c=JSON.parse(event.data).config;const prev=JSON.stringify([roomAssignments,widgetConfigs]);roomAssignments=c.rooms||{};widgetConfigs=c.widgets||[];if(prev!==JSON.stringify([roomAssignments,widgetConfigs])&&view!=='impostazioni')render()}catch(e){console.warn(e)}});stream.onerror=()=>{connected=false};}else setInterval(()=>{if(!requestRunning)refresh()},8000);
